"""Executable DuckDB reference implementation of the lakehouse contracts."""
from __future__ import annotations
import argparse, hashlib, json
from pathlib import Path
import duckdb
SPECIAL="'POST','DOT','C2','AMAZONFEE','BANK CHARGES','M','D','CRUK','B','S','23444','23574','22016','GIFT_0001_10','GIFT_0001_20','GIFT_0001_30','GIFT_0001_40','GIFT_0001_50'"
EXPECTED=['InvoiceNo','StockCode','Description','Quantity','InvoiceDate','UnitPrice','CustomerID','Country']
def run(source:Path,root:Path)->dict:
 source,root=Path(source),Path(root);out=root/'evidence';out.mkdir(parents=True,exist_ok=True);(root/'data/local').mkdir(parents=True,exist_ok=True)
 con=duckdb.connect(str(root/'data/local/retail_lakehouse.duckdb'))
 cols=[r[0] for r in con.execute("describe select * from read_csv_auto(?,all_varchar=true,header=true)",[str(source)]).fetchall()]
 if cols!=EXPECTED:raise ValueError(f'exact schema mismatch: {cols}')
 sha=hashlib.sha256(source.read_bytes()).hexdigest()
 con.execute("create or replace table bronze_invoice_lines as select *,filename source_file,row_number() over() source_row_number,current_timestamp ingested_at from read_csv_auto(?,all_varchar=true,header=true,filename=true)",[str(source)])
 con.execute("""create or replace table silver_quarantine as select *,case when InvoiceNo is null or StockCode is null then 'MISSING_BUSINESS_KEY' when try_cast(Quantity as integer) is null or try_cast(UnitPrice as decimal(18,4)) is null or try_strptime(InvoiceDate,'%Y-%m-%d %H:%M:%S') is null then 'TYPE_CONTRACT_FAILED' end quarantine_reason from bronze_invoice_lines where quarantine_reason is not null""")
 con.execute(f"""create or replace table silver_transactions as with typed as (select sha256(source_file||':'||source_row_number) transaction_key,source_file,source_row_number,trim(InvoiceNo) invoice_no,upper(trim(StockCode)) stock_code,nullif(trim(Description),'') description,cast(Quantity as integer) quantity,cast(InvoiceDate as timestamp) invoice_timestamp,cast(UnitPrice as decimal(18,4)) unit_price,nullif(trim(CustomerID),'') customer_id,nullif(trim(Country),'') country from bronze_invoice_lines b where not exists(select 1 from silver_quarantine q where q.source_file=b.source_file and q.source_row_number=b.source_row_number)),c as(select *,case when starts_with(invoice_no,'C') and quantity<0 and unit_price>0 then 'CANCELLATION' when not starts_with(invoice_no,'C') and quantity>0 and unit_price>0 then 'SALE' else 'ADJUSTMENT' end line_class,case when stock_code in ({SPECIAL}) then 'NON_MERCHANDISE_SERVICE_ACCOUNTING' when regexp_full_match(stock_code,'^[0-9]{{5}}[A-Z]{{0,2}}$') and description is not null then 'MERCHANDISE' else 'UNKNOWN_REVIEW' end item_type,quantity*unit_price line_value from typed) select *,case when item_type='MERCHANDISE' and line_class='SALE' then line_value else 0 end gross_merchandise_sales,case when item_type='MERCHANDISE' and line_class='CANCELLATION' then -line_value else 0 end cancellation_value,case when item_type='MERCHANDISE' and line_class='ADJUSTMENT' then line_value else 0 end adjustment_value,case when item_type='NON_MERCHANDISE_SERVICE_ACCOUNTING' then line_value else 0 end non_merchandise_signed_value,case when item_type='UNKNOWN_REVIEW' then line_value else 0 end unknown_review_signed_value from c qualify row_number() over(partition by transaction_key order by source_row_number)=1""")
 con.execute("alter table silver_transactions add column net_merchandise_value decimal(38,4)");con.execute("update silver_transactions set net_merchandise_value=gross_merchandise_sales-cancellation_value+adjustment_value")
 marts={'gold_daily_sales':"select cast(invoice_timestamp as date) sales_date,sum(gross_merchandise_sales) gross_sales,sum(cancellation_value) cancellation_exposure,sum(net_merchandise_value) net_value from silver_transactions group by 1",'gold_monthly_sales':"select date_trunc('month',invoice_timestamp) month_start,max(date_trunc('month',invoice_timestamp)) over()=date_trunc('month',invoice_timestamp) is_partial_month,count(distinct cast(invoice_timestamp as date)) observed_dates,sum(gross_merchandise_sales) gross_sales,sum(cancellation_value) cancellation_exposure,sum(net_merchandise_value) net_value from silver_transactions group by 1",'gold_product_performance':"select stock_code,max(description) description,sum(gross_merchandise_sales) gross_sales,sum(cancellation_value) cancellation_exposure,sum(net_merchandise_value) net_value from silver_transactions where item_type='MERCHANDISE' group by 1",'gold_country_performance':"select country,sum(gross_merchandise_sales) gross_sales,sum(cancellation_value) cancellation_exposure,sum(net_merchandise_value) net_value from silver_transactions where item_type='MERCHANDISE' group by 1",'gold_customer_rfm':"with p as(select customer_id,max(invoice_timestamp) last_purchase,count(distinct invoice_no) purchase_frequency,sum(gross_merchandise_sales) monetary from silver_transactions where customer_id is not null and item_type='MERCHANDISE' and line_class='SALE' group by 1)select *,datediff('day',last_purchase,(select max(invoice_timestamp)from silver_transactions)) recency_days,case when monetary>=2000 and purchase_frequency>=5 then 'CHAMPION' when purchase_frequency>=3 then 'LOYAL' else 'DEVELOPING' end segment from p",'gold_cohort_retention':"with a as(select customer_id,date_trunc('month',invoice_timestamp) activity_month,min(date_trunc('month',invoice_timestamp))over(partition by customer_id)cohort_month from silver_transactions where customer_id is not null and item_type='MERCHANDISE' and line_class='SALE'),d as(select distinct * from a)select cohort_month,date_diff('month',cohort_month,activity_month)month_number,count(*)active_customers from d group by 1,2",'gold_cancellation_exposure':"select stock_code,sum(cancellation_value)cancellation_exposure,count(*)cancellation_lines from silver_transactions where item_type='MERCHANDISE' and line_class='CANCELLATION' group by 1",'gold_data_quality_metrics':"select current_timestamp measured_at,(select count(*)from bronze_invoice_lines)bronze_rows,(select count(*)from silver_transactions)accepted_rows,(select count(*)from silver_quarantine)quarantine_rows,count(*)filter(where item_type='UNKNOWN_REVIEW')unknown_review_rows,cast(epoch(max(invoice_timestamp))as bigint)source_max_epoch_seconds from silver_transactions"}
 for n,q in marts.items():con.execute(f'create or replace table {n} as {q}')
 vals=con.execute("""select(select count(*)from bronze_invoice_lines),(select count(*)from silver_transactions),(select count(*)from silver_quarantine),count(*)filter(where item_type='MERCHANDISE'),count(*)filter(where item_type='NON_MERCHANDISE_SERVICE_ACCOUNTING'),count(*)filter(where item_type='UNKNOWN_REVIEW'),count(*)filter(where line_class='CANCELLATION'),round(sum(gross_merchandise_sales),2),round(sum(cancellation_value),2),round(sum(adjustment_value),2),round(sum(net_merchandise_value),2),round(sum(non_merchandise_signed_value),2),(select count(*)from gold_daily_sales),(select count(*)from gold_monthly_sales),(select count(*)from gold_product_performance),(select count(*)from gold_country_performance),(select count(*)from gold_customer_rfm),(select count(*)from gold_cohort_retention)from silver_transactions""").fetchone()
 keys=['source_rows','silver_accepted_rows','quarantine_rows','merchandise_rows','non_merchandise_rows','unknown_review_rows','cancellation_rows','gross_merchandise_sales','cancellation_value','adjustment_value','net_merchandise_value','non_merchandise_signed_value','daily_grain_rows','monthly_grain_rows','product_grain_rows','country_grain_rows','rfm_customer_rows','cohort_grain_rows'];m=dict(zip(keys,vals));m.update(cancellation_mart_rows=con.execute('select count(*) from gold_cancellation_exposure').fetchone()[0],source_max_epoch_seconds=con.execute('select epoch(max(invoice_timestamp))::bigint from silver_transactions').fetchone()[0],source_sha256=sha,accounting_balanced=m['source_rows']==m['silver_accepted_rows']+m['quarantine_rows'],partial_month_policy='latest source month labeled partial; exclude for completed-month comparisons',execution_boundary='Local DuckDB reference only; no Databricks workspace execution claimed')
 if not m['accounting_balanced']:raise RuntimeError('fail-closed: unaccounted rows')
 con.execute("create table if not exists audit_runs(run_id varchar primary key,source_sha256 varchar,status varchar,source_rows bigint,accepted_rows bigint,quarantine_rows bigint,completed_at timestamp)");rid=sha[:16];con.execute('delete from audit_runs where run_id=?',[rid]);con.execute('insert into audit_runs values(?,?,?,?,?,?,current_timestamp)',[rid,sha,'SUCCEEDED',m['source_rows'],m['silver_accepted_rows'],m['quarantine_rows']])
 for n in marts:con.execute(f"copy {n} to ?(format csv,header true)",[str(out/f'{n}.csv')])
 (out/'local_run_metrics.json').write_text(json.dumps(m,indent=2,sort_keys=True,default=str)+'\n',encoding='utf-8');con.close();return m
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--source',type=Path,required=True);p.add_argument('--root',type=Path,default=Path(__file__).parents[1]);a=p.parse_args();print(json.dumps(run(a.source,a.root),indent=2,default=str))
